package br.cofra.studio.rtmp;
import java.io.*;import java.util.*;
public final class FlvCodec {
 public static List<byte[]> nals(byte[] b)throws IOException{List<byte[]> result=new ArrayList<>();int first=start(b,0);if(first>=0&&first<4){for(int p=first;p>=0;){int skip=b[p+2]==1?3:4,a=p+skip,next=start(b,a),end=next<0?b.length:next;while(end>a&&b[end-1]==0)end--;if(end>a)result.add(Arrays.copyOfRange(b,a,end));p=next;}}else{int p=0;while(p+4<=b.length){int n=(b[p]&255)<<24|(b[p+1]&255)<<16|(b[p+2]&255)<<8|b[p+3]&255;p+=4;if(n<1||n>b.length-p)throw new IOException("NAL inválido");result.add(Arrays.copyOfRange(b,p,p+n));p+=n;}if(p!=b.length)throw new IOException("NAL truncado");}if(result.isEmpty())throw new IOException("Vídeo vazio");return result;}
 private static int start(byte[] b,int from){for(int i=from;i+2<b.length;i++)if(b[i]==0&&b[i+1]==0&&(b[i+2]==1||i+3<b.length&&b[i+2]==0&&b[i+3]==1))return i;return -1;}
 public static byte[] avcConfig(byte[] a,byte[] b)throws IOException{if(a.length>6&&a[0]==1)return prepend(new byte[]{0x17,0,0,0,0},a);List<byte[]> list=new ArrayList<>(nals(a));if(b!=null&&b.length>0)list.addAll(nals(b));byte[] s=null,p=null;for(byte[] n:list){if((n[0]&31)==7)s=n;if((n[0]&31)==8)p=n;}if(s==null||s.length<4||p==null)throw new IOException("SPS/PPS ausentes");ByteArrayOutputStream out=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(out);d.write(new byte[]{0x17,0,0,0,0,1,s[1],s[2],s[3],(byte)255,(byte)225});d.writeShort(s.length);d.write(s);d.writeByte(1);d.writeShort(p.length);d.write(p);return out.toByteArray();}
 public static byte[] video(byte[] bytes,boolean key)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(out);d.write(new byte[]{(byte)(key?0x17:0x27),1,0,0,0});for(byte[] n:nals(bytes)){int type=n[0]&31;if(type==7||type==8||type==9)continue;d.writeInt(n.length);d.write(n);}return out.toByteArray();}
 public static byte[] audio(byte[] b,boolean config){return prepend(new byte[]{(byte)0xaf,(byte)(config?0:1)},b);}
 private static byte[] prepend(byte[] prefix,byte[] data){byte[] out=Arrays.copyOf(prefix,prefix.length+data.length);System.arraycopy(data,0,out,prefix.length,data.length);return out;}
}
